(function bootstrapV37Defaults() {
  try {
    const existingList = JSON.parse(localStorage.getItem('CBT_MAPEL_LIST_V1') || 'null');
    if (!Array.isArray(existingList) || existingList.length < 10) {
      localStorage.setItem('CBT_MAPEL_LIST_V1', JSON.stringify(DEFAULT_OFFICIAL_SUBJECTS));
    }
    const existingMeta = JSON.parse(localStorage.getItem('CBT_MAPEL_META_V1') || 'null') || {};
    localStorage.setItem('CBT_MAPEL_META_V1', JSON.stringify({ ...DEFAULT_OFFICIAL_SUBJECTS_META, ...existingMeta }));
  } catch (e) {}
})();


function loadSavedClassesMeta() {
  try {
    const rawStr = localStorage.getItem(CLASSES_META_KEY);
    if (rawStr !== null) {
      const raw = JSON.parse(rawStr);
      if (Array.isArray(raw)) return raw;
    }
  } catch (e) {}
  return [];
}

