// ============================================================================
// HELPER MASTER KELAS, ID KELAS & WALI KELAS
// ============================================================================
function getClassesList(db = getDB()) {
  if (Array.isArray(db.classesList)) return db.classesList;
  return loadSavedClassesMeta();
}

function resolveIdKelasFromName(namaKelas, classesList = getClassesList()) {
  if (!namaKelas || namaKelas === '-') return '-';
  const found = classesList.find(c => c.namaKelas.toLowerCase() === String(namaKelas).trim().toLowerCase());
  return found ? found.idKelas : '-';
}

function parseSubjectsString(rawStr) {
  if (!rawStr || rawStr === '-') return [];
  if (Array.isArray(rawStr)) {
    return rawStr.map(s => String(s || '').trim()).filter(s => s && s !== '-');
  }
  return String(rawStr)
    .split(/[,;|]+/)
    .map(s => s.trim())
    .filter(s => s && s !== '-');
}

function getAllSubjectsList(db = getDB()) {
  const saved = JSON.parse(localStorage.getItem('CBT_MAPEL_LIST_V1') || 'null');
  const set = new Set([
    ...(typeof DEFAULT_OFFICIAL_SUBJECTS !== 'undefined' ? DEFAULT_OFFICIAL_SUBJECTS : []),
    ...(Array.isArray(saved) ? saved : [])
  ]);
  if (db.settings && db.settings.subject) set.add(db.settings.subject);
  if (Array.isArray(db.settings?.subjectsList)) {
    db.settings.subjectsList.forEach(m => { if (m) set.add(m); });
  }
  (db.questions || []).forEach(q => { if (q.subject) set.add(q.subject); });
  (db.users || []).forEach(u => {
    if (u.role === 'Guru' && u.kelas && u.kelas !== '-') {
      parseSubjectsString(u.kelas).forEach(m => set.add(m));
    }
    if ((u.role === 'Guru' || u.role === 'Wali Kelas') && u.subject && u.subject !== '-') {
      parseSubjectsString(u.subject).forEach(m => set.add(m));
    }
  });
  Object.values(db.sessions || {}).forEach(s => {
    if (s.subjectResults) {
      Object.keys(s.subjectResults).forEach(m => set.add(m));
    }
  });
  return Array.from(set);
}

function inferJenjangFromClassName(namaKelas) {
  const info = parseStudentGradeInfo(namaKelas);
  if (info.gradeNum !== null) {
    if (info.gradeNum >= 1 && info.gradeNum <= 3) return 'SD Rendah (Kelas 1-3)';
    if (info.gradeNum >= 4 && info.gradeNum <= 6) return 'SD Tinggi (Kelas 4-6)';
    if (info.gradeNum === 7) return 'SMP Kelas 7';
    if (info.gradeNum === 8) return 'SMP Kelas 8';
    if (info.gradeNum === 9) return 'SMP Kelas 9';
    if (info.gradeNum >= 10 && info.gradeNum <= 12) return 'SMK (Kelas 10-12)';
  }
  if (info.jenjang === 'SD') return 'SD (Semua Kelas 1-6)';
  if (info.jenjang === 'SMP') return 'SMP (Kelas 7-9)';
  if (info.jenjang === 'SMK') return 'SMK (Kelas 10-12)';
  return '';
}

function getWaliHeldSubjects(clsOrIdKelas, db = getDB()) {
  const classes = getClassesList(db);
  const clsObj = (typeof clsOrIdKelas === 'object' && clsOrIdKelas !== null)
    ? clsOrIdKelas
    : classes.find(c => c.idKelas === clsOrIdKelas);
  if (!clsObj) return [];

  const held = new Set(parseSubjectsString(clsObj.waliMapelList || []));
  const waliUser = (db.users || []).find(u =>
    u.role === 'Wali Kelas' && (
      (clsObj.waliKelasUsername && u.username === clsObj.waliKelasUsername) ||
      (clsObj.idKelas && u.idKelas === clsObj.idKelas)
    )
  );
  if (waliUser && waliUser.subject && waliUser.subject !== '-') {
    parseSubjectsString(waliUser.subject).forEach(m => held.add(m));
  }
  return Array.from(held);
}

function getClassSubjectsList(clsOrIdKelas, db = getDB()) {
  const allSubjects = getAllSubjectsList(db);
  const classes = getClassesList(db);
  const clsObj = (typeof clsOrIdKelas === 'object' && clsOrIdKelas !== null)
    ? clsOrIdKelas
    : classes.find(c => c.idKelas === clsOrIdKelas);

  if (!clsObj) return allSubjects;

  const heldByWali = getWaliHeldSubjects(clsObj, db);
  const explicitClassMapels = parseSubjectsString(clsObj.subjectsList || []);

  // Jika admin sudah menetapkan daftar mapel khusus pada kelas ini
  if (explicitClassMapels.length > 0) {
    const merged = new Set(explicitClassMapels);
    heldByWali.forEach(m => merged.add(m));
    return Array.from(merged);
  }

  // Cocokkan berdasarkan jenjang kelas atau nama kelas
  const levelHint = (clsObj.jenjang && clsObj.jenjang !== '-' && clsObj.jenjang !== 'Semua Jenjang')
    ? clsObj.jenjang
    : (clsObj.namaKelas || '');

  if (!levelHint || levelHint === '-') {
    return allSubjects;
  }

  const matched = allSubjects.filter(subj => doesSubjectMatchStudentClass(subj, levelHint, db));
  const resultSet = new Set(matched.length > 0 ? matched : allSubjects);
  heldByWali.forEach(m => resultSet.add(m));
  return Array.from(resultSet);
}

function getStudentsByClassId(idKelas, db = getDB()) {
  const classes = getClassesList(db);
  const clsObj = classes.find(c => c.idKelas === idKelas);
  const targetNamaKelas = clsObj ? clsObj.namaKelas.toLowerCase() : '';

  const siswaUsers = (db.users || []).filter(u => {
    if (u.role !== 'Siswa') return false;
    if (u.idKelas && u.idKelas === idKelas) return true;
    if (targetNamaKelas && u.kelas && u.kelas.toLowerCase() === targetNamaKelas) return true;
    return false;
  });

  const seenIds = new Set();
  const result = [];

  siswaUsers.forEach(u => {
    seenIds.add(u.username);
    const sess = (db.sessions || {})[u.username] || {
      studentId: u.username,
      name: u.name,
      kelas: u.kelas,
      idKelas: u.idKelas || idKelas,
      ruang: u.ruang || '-',
      status: 'Belum Ujian',
      answers: {},
      essayScores: {},
      subjectResults: {}
    };
    result.push({
      studentId: u.username,
      name: u.name,
      kelas: u.kelas || (clsObj ? clsObj.namaKelas : '-'),
      idKelas: u.idKelas || idKelas,
      session: sess
    });
  });

  Object.values(db.sessions || {}).forEach(s => {
    if (seenIds.has(s.studentId)) return;
    const matchById = s.idKelas && s.idKelas === idKelas;
    const matchByName = targetNamaKelas && s.kelas && s.kelas.toLowerCase() === targetNamaKelas;
    if (matchById || matchByName) {
      seenIds.add(s.studentId);
      result.push({
        studentId: s.studentId,
        name: s.name,
        kelas: s.kelas,
        idKelas: s.idKelas || idKelas,
        session: s
      });
    }
  });

  return result;
}

// Helper: Hitung & Ambil Rekap Nilai per Mata Pelajaran untuk setiap peserta
function getStudentSubjectMetrics(session, subjectName, db = getDB()) {
  const defaultSubj = db.settings?.subject || 'Informatika & Literasi Digital';
  const subjQuestions = (db.questions || []).filter(q => (q.subject || defaultSubj) === subjectName);

  const savedRes = (session.subjectResults && session.subjectResults[subjectName]) || null;
  const answers = session.answers || {};
  const essayScores = session.essayScores || {};

  let autoScore = 0;
  let essayScore = 0;
  let answeredCount = 0;

function isCbtAnswerCorrect(q, userRawAns) {
  if (!q) return false;
  const ans = String(userRawAns || '').trim();
  if (!ans) return false;
  if (q.type === 'ISIAN') {
    return stripHtmlToPlainText(ans).toLowerCase() === stripHtmlToPlainText(q.answer || '').toLowerCase();
  }
  if (q.type === 'PGK') {
    const userSet = Array.from(new Set(ans.split('||').map(x => normalizeAnswerValue(x)).filter(Boolean))).sort();
    const keySet = Array.from(new Set(String(q.answer || '').split('||').map(x => normalizeAnswerValue(x)).filter(Boolean))).sort();
    if (keySet.length === 0 || userSet.length !== keySet.length) return false;
    return userSet.every((val, idx) => val === keySet[idx]);
  }
  return normalizeAnswerValue(ans) === normalizeAnswerValue(q.answer);
}

  subjQuestions.forEach(q => {
    const ans = (answers[q.id] || '').trim();
    if (ans) answeredCount++;
    if (q.type === 'ESAI') {
      essayScore += Number(essayScores[q.id] || 0);
    } else if (ans) {
      if (isCbtAnswerCorrect(q, ans)) autoScore += Number(q.weight || 0);
    }
  });

  if (subjQuestions.length > 0 && (answeredCount > 0 || essayScore > 0)) {
    const isCurrentActiveSubj = (db.settings?.subject === subjectName);
    const status = savedRes?.status || (isCurrentActiveSubj ? session.status : 'Selesai');
    const submittedAt = savedRes?.submittedAt || (isCurrentActiveSubj ? session.submittedAt : null);
    return {
      subject: subjectName,
      questionCount: subjQuestions.length,
      answeredCount,
      autoScore,
      essayScore,
      finalScore: autoScore + essayScore,
      status,
      submittedAt
    };
  }

  if (savedRes) {
    return {
      subject: subjectName,
      questionCount: subjQuestions.length,
      answeredCount: savedRes.answeredCount || 0,
      autoScore: Number(savedRes.autoScore || 0),
      essayScore: Number(savedRes.essayScore || 0),
      finalScore: Number(savedRes.finalScore || 0),
      status: savedRes.status || 'Selesai',
      submittedAt: savedRes.submittedAt || null
    };
  }

  const isCurrentActiveSubj = (db.settings?.subject === subjectName);
  return {
    subject: subjectName,
    questionCount: subjQuestions.length,
    answeredCount: 0,
    autoScore: 0,
    essayScore: 0,
    finalScore: 0,
    status: isCurrentActiveSubj ? (session.status || 'Siap Ujian') : 'Belum Ujian',
    submittedAt: null
  };
}

function downloadCSV(filename, rows) {
  const csvContent = rows.map(r => r.map(v => `"${String(v ?? '').replace(/"/g, '""')}"`).join(',')).join('\n');
  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = filename;
  link.click();
}

